 g.textAlign="right";g.fillStyle=frac<0.5?"#8fe3a6":frac<0.78?"#ffd23a":"#ff6a5a";g.font="800 16px -apple-system,sans-serif";g.fillText(Math.round(frac*100),bx+bw,y0+19);
