 for(let i=0;i<waterPts.length;i++){const p=waterPts[i],sx=toX(p[0]),sy=toY(p[1]);if(sx<-20||sy<-20||sx>W+20||sy>H+20)continue;
  const tw=0.5+0.5*Math.sin(t*1.7+p[0]*40+p[1]*30),a=0.17*tw;if(a<0.02)continue;const rr=S*0.014*(0.6+0.9*tw);
  g.globalAlpha=a;g.fillStyle="#eaf7ff";g.beginPath();g.ellipse(sx+Math.sin(t*0.9+i)*S*0.006,sy,rr*1.9,rr*0.5,0,0,7);g.fill();}
