 if(waterBB){const per=2.4;for(let k=0;k<2;k++){const ph=((t/per)+k*0.5)%1,idx=((k*97+Math.floor(t/per))%Math.max(1,waterPts.length));const wp=waterPts[idx%waterPts.length];if(wp){const sx=toX(wp[0]),sy=toY(wp[1]),rr=S*0.05*ph;g.globalAlpha=0.22*(1-ph);g.strokeStyle="#dff2ff";g.lineWidth=1.4;g.beginPath();g.ellipse(sx,sy,rr,rr*0.42,0,0,7);g.stroke();}}g.globalAlpha=1;}
